/// @file eranos.hpp
/// The eranos library for C++23: groups that share expenses, their members, entries, totals, and settlements.
///
/// Every call reaches the library through its C API, whose classes, generated by Diplomat, live in eranos::detail and
/// are not part of this layer. A failure the library reports throws eranos::Error. Every group call has a synchronous
/// form, which blocks the calling thread while another call holds the group's lock, and an asynchronous one, whose name
/// ends in Async and which returns a std::future: it runs on the group's worker thread, in the order of the calls, and
/// its future's get() throws what the synchronous form throws.
///
/// The layer is split into parts by what they hold, under eranos/; this header includes every part, and then the
/// conversions that the parts' functions call, which need every type complete.

#ifndef ERANOS_HPP
#define ERANOS_HPP

#include "eranos/calendar.hpp"     // IWYU pragma: export
#include "eranos/category.hpp"     // IWYU pragma: export
#include "eranos/contact.hpp"      // IWYU pragma: export
#include "eranos/currency.hpp"     // IWYU pragma: export
#include "eranos/error.hpp"        // IWYU pragma: export
#include "eranos/expense.hpp"      // IWYU pragma: export
#include "eranos/failures.hpp"     // IWYU pragma: export
#include "eranos/group.hpp"        // IWYU pragma: export
#include "eranos/group_reader.hpp" // IWYU pragma: export
#include "eranos/identifiers.hpp"  // IWYU pragma: export
#include "eranos/members.hpp"      // IWYU pragma: export
#include "eranos/money.hpp"        // IWYU pragma: export
#include "eranos/ratios.hpp"       // IWYU pragma: export
#include "eranos/split.hpp"        // IWYU pragma: export
#include "eranos/totals.hpp"       // IWYU pragma: export
#include "eranos/transfer.hpp"     // IWYU pragma: export

#include "eranos/detail/conversions.hpp"

#endif // ERANOS_HPP
